'use strict';
// The live services are deliberately gated until a real server API is configured.
const guides = [
 {id:'start',name:'เริ่มต้นที่ Luma',category:'เริ่มเล่น',zone:'welcome',icon:'book',summary:'เข้าเมือง รับของเริ่มต้น และหาบทบาทที่ชอบ',body:['เป้าหมายคือ Minecraft Java 1.16.5 ขึ้นไป เวอร์ชันที่รองรับจริงจะประกาศหลังทดสอบ','เริ่มที่ลานคริสตัล แล้วแวะหอรับรองเพื่อรับคู่มือและของเริ่มต้น','Roleplay เป็นทางเลือก เล่นเควส เก็บของ หรือตกปลาตามปกติได้ ไม่ต้องส่งประวัติตัวละคร'],commands:['/help','/spawn']},
 {id:'bank',name:'ธนาคารและเงิน',category:'เศรษฐกิจ',zone:'bank',icon:'chest',summary:'เงินติดตัว เงินฝาก และประวัติรายการ',body:['แยกเงินติดตัวกับเงินฝาก เพื่อให้ดูยอดได้ชัดเจน','ตรวจยอดและค่าธรรมเนียมก่อนฝากหรือถอน หากรายการผิดพลาดให้ใช้เลขอ้างอิงแจ้งทีมงาน','สกุลเงินและค่าธรรมเนียมอยู่ระหว่างออกแบบ ยังไม่มีราคาใช้งานจริง'],commands:['/bank']},
 {id:'forge',name:'ซ่อมและสร้างอุปกรณ์',category:'อุปกรณ์',zone:'forge',icon:'sword',summary:'ซ่อมของเดิม สร้างไอเทม และฝังอัญมณี',body:['นำอุปกรณ์ไปพบช่างในโรงตีเหล็กรูน','ดูราคาซ่อมและความทนทานหลังซ่อมก่อนยืนยัน','ระบบต้องเก็บค่าสถานะ อัญมณี และข้อมูลเฉพาะของชิ้นเดิมไว้ครบ'],commands:['/repair']},
 {id:'quest',name:'เควสและปาร์ตี้',category:'ผจญภัย',zone:'quest',icon:'book',summary:'เลือกภารกิจและออกเดินทางกับเพื่อน',body:['บอร์ดนักผจญภัยจะแสดงระดับ เงื่อนไข และรางวัลก่อนรับเควส','ภารกิจประจำวันและเนื้อเรื่องมีความคืบหน้าแยกกัน','การแบ่งรางวัลของปาร์ตี้จะบอกก่อนเริ่ม เพื่อให้ทุกคนเลือกเข้าร่วมได้'],commands:['/quest','/party']},
 {id:'jobs',name:'อาชีพและบทบาท',category:'เริ่มเล่น',zone:'jobs',icon:'pick',summary:'นักขุด พ่อค้า นักตกปลา หรือนักผจญภัย',body:['ทดลองอาชีพที่ลานฝึกก่อนตัดสินใจ','อาชีพเป็นเส้นทางเล่นระยะยาว ส่วนบทบาทในเมืองเลือกเล่นตามจังหวะของคุณได้','รายได้ โบนัส และข้อจำกัดการเปลี่ยนอาชีพจะประกาศเมื่อสูตรผ่านการทดสอบ'],commands:['/jobs']},
 {id:'market',name:'ตลาดผู้เล่น',category:'เศรษฐกิจ',zone:'market',icon:'chest',summary:'ดูราคา ค่าธรรมเนียม และสถานะสินค้าที่ขาย',body:['ตลาดแสดงไอเทมจริงพร้อมรายละเอียดก่อนซื้อ','ของที่ประกาศขายต้องฝากในระบบ จึงไม่หายเมื่อผู้ขายออกจากเกม','ของที่รับไม่ทันหรือกระเป๋าเต็มจะอยู่ในกล่องจดหมาย'],commands:['/market','/mail']},
 {id:'guild',name:'กิลด์และเพื่อนร่วมเมือง',category:'ชุมชน',zone:'guild',icon:'banner',summary:'รวมทีม สร้างกิลด์ และนัดพบเพื่อน',body:['ใช้หอกิลด์เป็นจุดนัดพบและจัดกิจกรรมร่วมกัน','เจ้าของกิลด์กำหนดสิทธิ์สมาชิกได้ ไม่แชร์สิทธิ์ดูแลเซิร์ฟ','ชื่อกิลด์และข้อความสาธารณะต้องสุภาพและไม่แอบอ้างทีมงาน'],commands:['/guild']},
 {id:'pets',name:'สัตว์เลี้ยงและตกปลา',category:'ชุมชน',zone:'pets',icon:'gem',summary:'พักจากการผจญภัย เก็บบันทึกปลาและสัตว์เลี้ยง',body:['สวนริมบ่อเป็นพื้นที่พักผ่อนที่ไม่บังคับต่อสู้','สัตว์เลี้ยงติดตามเจ้าของและต้องไม่บังเคาน์เตอร์หรือทางเดิน','การแข่งขันตกปลาจะประกาศเวลาและกติกาก่อนเริ่ม'],commands:['/pets']},
 {id:'rules',name:'กติกาและ Roleplay',category:'ชุมชน',icon:'book',summary:'เล่นสบาย ๆ เคารพพื้นที่ของกันและกัน',body:['Roleplay กับผู้เล่นที่ยินดีเข้าร่วม ไม่บังคับใช้เสียงหรือเล่นบทตลอดเวลา','ไม่ขโมยข้อมูลบัญชี ไม่ใช้โปรแกรมโกง และไม่รบกวนการเล่นของผู้อื่น','หากพบของซ้ำ ยอดเงินผิด หรือช่องโหว่ ให้เก็บเลขรายการและแจ้งทีมงาน ไม่เผยแพร่วิธีใช้ช่องโหว่'],commands:[]}
];
const serviceChecks=[['เซิร์ฟ Minecraft','รอเปิดบริการ','ยังไม่มี IP ที่ประกาศ'],['แผนที่ 3D','รอเชื่อมโลก','แสดงแผนผังคอนเซปต์ได้แล้ว'],['บัญชีและตัวละคร','รอเชื่อมเซิร์ฟ','ต้องยืนยัน UUID ผ่านรหัส /link'],['ร้านค้าและชำระเงิน','ยังไม่เปิดรับชำระ','รอผู้ให้บริการรับเงินและระบบคำสั่งซื้อ'],['ส่งของเข้าเกม','รอทดสอบระบบ','เตรียมคิวส่งมอบและกล่องจดหมาย'],['อันดับและกิจกรรม','รอข้อมูลเกม','ไม่มีคะแนนหรือผู้เล่นตัวอย่างที่อ้างว่าเป็นข้อมูลจริง']];
let guideCategory='ทั้งหมด',guideQuery='',accountSection='overview',rankingCategory='การผจญภัย';
function pixelIcon(kind){const paths={gem:'M12 2 3 9l9 13 9-13z M3 9h18 M8 9l4 13 4-13 M8 9l4-7 4 7',chest:'M3 7h18v14H3z M3 12h18 M10 10h4v5h-4z M5 3h14v4',sword:'M16 2h6v6L10 20l-6-6z M7 17l-5 5 M2 12l10 10',book:'M12 6c-3-3-6-3-10-2v16c4-1 7-1 10 2 3-3 6-3 10-2V4c-4-1-7-1-10 2z M12 6v16 M5 9h4 M15 9h4 M5 13h4 M15 13h4',pick:'M3 3h14l4 4-3 3-4-4H3z M13 6 3 22',banner:'M5 22V2h14v13l-7-3-7 3',portal:'M5 22V4l7-2 7 2v18 M9 22V8h6v14'};return `<svg class="pixel-icon" viewBox="0 0 24 24" fill="none" stroke="currentColor" stroke-width="1.7" stroke-linejoin="miter" aria-hidden="true"><path d="${paths[kind]||paths.gem}"/></svg>`}
function pageHead(label,title,description){return `<div class="page-head"><p class="meta">${label}</p><h1>${title}</h1><p>${description}</p></div>`}
function portalHome(){return `<div class="portal-shell"><section class="town-hero"><img class="hero-world" src="assets/city.webp" alt="ภาพคอนเซปต์เมือง Minecraft Luma พร้อมปราสาทและคริสตัล" fetchpriority="high"><div class="hero-shade"></div><div class="hero-content"><p class="eyebrow"><span class="square-mark"></span> MINECRAFT · FANTASY · CASUAL ROLEPLAY</p><img class="hero-brand" src="assets/luma-logo.webp" alt="Luma Fantasy Town" width="400" height="160"><h1>เรื่องราวใหม่<br>เริ่มที่เมืองของเรา</h1><p>ออกผจญภัย เปิดร้าน สร้างกิลด์ หรือพักตกปลากับเพื่อน<br>เลือกเป็นตัวเองได้ในโลกแฟนตาซีของ Luma</p><div class="actions"><button class="button" data-join>${pixelIcon('portal')} วิธีเข้าเล่น</button><a class="hero-map-link" href="#map">เปิดแผนที่เมือง</a></div></div><div class="hero-side"><span class="map-label">THE CRYSTAL DISTRICT</span><span>ภาพแนวทางการสร้างเมือง</span></div><div class="hero-foot"><div><span class="meta">EDITION</span><strong>Java 1.16.5+</strong><small>รุ่นเป้าหมาย</small></div><div><span class="meta">PLAY YOUR WAY</span><strong>Roleplay แบบสบาย ๆ</strong><small>ไม่บังคับใช้เสียง</small></div><a href="#status"><span class="meta">SERVER</span><strong>อยู่ระหว่างพัฒนา</strong><small>ดูสถานะบริการ</small></a></div></section>
<nav class="quick-dock" aria-label="ทางลัดระบบ"><a href="#map">${pixelIcon('portal')}<span>แผนที่เมือง<small>ค้นหาทั้ง 12 โซน</small></span></a><a href="#wiki">${pixelIcon('book')}<span>คู่มือผู้เล่น<small>เริ่มเล่นและระบบเกม</small></span></a><a href="#events">${pixelIcon('banner')}<span>กิจกรรม<small>ติดตามแผนกิจกรรม</small></span></a><a href="#shop">${pixelIcon('gem')}<span>ร้านค้าของตกแต่ง<small>ดูชุดไอเทมของ Luma</small></span></a></nav>
<div class="hub-layout"><div><section><div class="section-heading"><div><p class="meta">TOWN JOURNAL</p><h2>ข่าวจากเมือง</h2></div><a class="text-link" href="#news">ข่าวทั้งหมด</a></div><div class="journal-feature"><img src="assets/03-quest-lodge.webp" alt="กระท่อมนักผจญภัย Minecraft" loading="lazy"><div><span class="tag">ชุมชน</span><h3>มีบทบาทให้เล่น<br>มีพื้นที่ให้เป็นตัวเอง</h3><p>เป็นนักผจญภัย พ่อค้า หรือนักตกปลาได้โดยไม่ต้องเล่นตามบทตลอดเวลา</p><button class="text-button" data-news="rp">อ่านแนวทาง Roleplay</button></div></div><div class="brief-list">${news.filter(n=>n.id!=='rp').map(n=>`<article class="brief-row"><span>${n.category}</span><h3>${n.title}</h3><button data-news="${n.id}" aria-label="อ่าน ${n.title}">อ่าน</button></article>`).join('')}</div></section>
<section class="systems-section"><div class="section-heading"><div><p class="meta">CITY SERVICES</p><h2>ทุกเส้นทางมีเรื่องให้ทำ</h2></div><a class="text-link" href="#wiki">ดูระบบทั้งหมด</a></div><div class="service-grid">${['bank','forge','quest','market'].map(id=>{const z=zones.find(z=>z.id===id);return `<a class="service-tile" href="#map" data-map-link="${id}"><img src="assets/${z.image}" alt="${z.name}" loading="lazy"><div>${pixelIcon(id==='forge'?'sword':id==='quest'?'book':'chest')}<h3>${z.name}</h3><p>${z.services.slice(0,2).join(' · ')}</p></div></a>`}).join('')}</div></section></div>
<aside class="hub-aside"><section class="panel get-started"><p class="meta">YOUR FIRST ADVENTURE</p><h2>มาเป็นส่วนหนึ่ง<br>ของเมือง</h2><ol class="step-list"><li><span>01</span><div>เตรียม Minecraft Java<small>รุ่นเป้าหมาย 1.16.5 ขึ้นไป</small></div></li><li><span>02</span><div>อ่านคู่มือเริ่มเล่น<small>รู้จักเมืองและกติกา</small></div></li><li><span>03</span><div>ติดตามวันเปิดเซิร์ฟ<small>IP จะประกาศเมื่อพร้อม</small></div></li></ol><a class="button secondary" href="#wiki">เปิดคู่มือผู้เล่น</a></section><section class="panel"><div class="panel-heading"><h2>สถานะบริการ</h2><a href="#status">รายละเอียด</a></div><div class="status-line"><span>เซิร์ฟเกม</span><span class="state pending">รอเปิดบริการ</span></div><div class="status-line"><span>แผนที่สด</span><span class="state pending">รอเชื่อมต่อ</span></div><div class="status-line"><span>ร้านค้า</span><span class="state pending">ยังไม่รับชำระ</span></div></section><section class="guild-banner"><span class="meta">FIND YOUR PARTY</span><h2>การผจญภัย<br>ดีกว่าเมื่อมีเพื่อน</h2><p>รู้จักปาร์ตี้ กิลด์ และเควสของเมือง</p><a class="text-link" href="#wiki" data-guide-link="quest">อ่านเรื่องเควสและปาร์ตี้</a></section></aside></div></div>`}
function wikiPage(){return `<div class="shell">${pageHead('PLAYER HANDBOOK','คู่มือเมือง Luma','ค้นหาระบบที่สนใจ แล้วดูวิธีเล่นและโซนบริการได้ในที่เดียว')}<p class="notice">คู่มือฉบับวางแผน • คำสั่งและสูตรจะยืนยันอีกครั้งก่อนเปิดเซิร์ฟ</p><div class="toolbar"><div class="field grow"><label for="guide-search">ค้นหาคู่มือ</label><input id="guide-search" type="search" placeholder="เช่น ซ่อม เงิน กิลด์" value="${escapeHTML(guideQuery)}"></div></div><div class="pill-row">${['ทั้งหมด','เริ่มเล่น','เศรษฐกิจ','อุปกรณ์','ผจญภัย','ชุมชน'].map(c=>`<button class="pill" data-guide-category="${c}" aria-pressed="${guideCategory===c}">${c}</button>`).join('')}</div><div id="guide-results" class="guide-grid">${guideCards()}</div></div>`}
function guideCards(){const list=guides.filter(g=>(guideCategory==='ทั้งหมด'||g.category===guideCategory)&&`${g.name} ${g.summary} ${g.body.join(' ')}`.includes(guideQuery));return list.length?list.map(g=>`<button class="guide-card" data-guide="${g.id}">${pixelIcon(g.icon)}<span class="meta">${g.category}</span><h2>${g.name}</h2><p>${g.summary}</p><span class="text-link">อ่านคู่มือ</span></button>`).join(''):'<div class="empty">ไม่พบคู่มือนี้ ลองค้นหาด้วยชื่อระบบอื่น</div>'}
function openGuide(id){const g=guides.find(g=>g.id===id);if(!g)return;modal(`<article class="article"><p class="meta">${g.category}</p><h2 id="dialog-title">${g.name}</h2>${g.body.map(p=>`<p>${p}</p>`).join('')}${g.commands.length?`<div class="command-list">${g.commands.map(c=>`<code>${c}</code>`).join('')}</div><p class="fine">คำสั่งที่เสนอสำหรับระบบจริง</p>`:''}${g.zone?`<a class="button secondary" href="#map" data-map-link="${g.zone}">ดูโซนบริการ</a>`:''}</article>`)}
function eventsPage(){return `<div class="shell">${pageHead('TOWN CALENDAR','กิจกรรมของเมือง','เควสชุมชน วันรวมกิลด์ และกิจกรรมที่เล่นได้ตามจังหวะของคุณ')}<p class="notice">แผนกิจกรรม • ยังไม่ประกาศวันเริ่มหรือเปิดลงทะเบียน</p><div class="event-layout"><article class="event-feature"><img src="assets/09-portals-adventure.webp" alt="ประตูการผจญภัย Luma" loading="lazy"><div><span class="tag">กำลังวางแผน</span><h2>เปิดประตูสู่<br>การผจญภัยครั้งแรก</h2><p>เตรียมเส้นทางสำรวจ เควสเริ่มต้น และกลุ่มนักผจญภัยสำหรับวันเปิดเมือง</p><button class="button secondary" data-guide="quest">อ่านคู่มือเควส</button></div></article><div class="event-list">${[['ตลาดกลางคืน','วันรวมตัวของพ่อค้าและผู้เล่น','06-fantasy-market.webp','market'],['เทศกาลนักตกปลา','กิจกรรมพักผ่อนริมบ่อในเมือง','10-pets-fishing.webp','pets'],['คืนรวมกิลด์','นัดพบเพื่อนและเตรียมปาร์ตี้','04-guild-arcane-hall.webp','guild']].map(e=>`<article><img src="assets/${e[2]}" alt="${e[0]}" loading="lazy"><div><span class="meta">ยังไม่กำหนดวัน</span><h2>${e[0]}</h2><p>${e[1]}</p><button class="text-button" data-guide="${e[3]}">ดูระบบที่เกี่ยวข้อง</button></div></article>`).join('')}</div></div></div>`}
function rankingsPage(){return `<div class="shell">${pageHead('HALL OF ADVENTURERS','บันทึกนักผจญภัย','อันดับตามฤดูกาล แยกตามรูปแบบการเล่น')}<div class="pill-row">${['การผจญภัย','อาชีพ','ตกปลา','กิลด์'].map(c=>`<button class="pill" data-ranking="${c}" aria-pressed="${rankingCategory===c}">${c}</button>`).join('')}</div><section class="ranking-panel"><div class="ranking-head"><h2 id="ranking-title">${rankingCategory}</h2><span class="state pending">รอข้อมูลจากเกม</span></div><div class="empty large-empty">${pixelIcon('banner')}<h3>เรื่องราวของนักผจญภัยยังไม่เริ่ม</h3><p>อันดับจริงจะปรากฏเมื่อเซิร์ฟเปิดบริการและเชื่อมข้อมูลฤดูกาล</p><a class="text-link" href="#wiki">เตรียมตัวก่อนออกผจญภัย</a></div></section></div>`}
function statusPage(){return `<div class="shell">${pageHead('SERVICE STATUS','สถานะระบบ Luma','ตรวจความพร้อมของบริการก่อนเข้าเล่นหรือซื้อสินค้า')}<div class="status-summary">${pixelIcon('portal')}<div><h2>เมืองอยู่ระหว่างพัฒนา</h2><p>ยังไม่มีข้อมูลออนไลน์จากเซิร์ฟ Minecraft</p></div></div><div class="service-status-list">${serviceChecks.map(s=>`<article><h2>${s[0]}</h2><p>${s[2]}</p><span class="state pending">${s[1]}</span></article>`).join('')}</div></div>`}
function portalAccount(){const tabs=[['overview','เชื่อมบัญชี'],['orders','รายการซื้อ'],['mail','กล่องจดหมาย'],['settings','ตั้งค่า']];return `<div class="shell">${pageHead('PLAYER CENTER','ศูนย์บัญชีผู้เล่น','เชื่อมตัวละคร ติดตามรายการซื้อ และรับของที่ส่งเข้าเกม')}<div class="account-top"><div class="avatar-placeholder">${pixelIcon('gem')}</div><div><h2>ยังไม่ได้เชื่อมตัวละคร</h2><p class="fine">ยืนยันบัญชี Minecraft ก่อนดูข้อมูลส่วนตัว</p></div><span class="state pending">ยังไม่เชื่อมเซิร์ฟ</span></div><div class="pill-row account-tabs">${tabs.map(([id,name])=>`<button class="pill" data-account-tab="${id}" aria-pressed="${accountSection===id}">${name}</button>`).join('')}</div><div id="account-content">${accountContent()}</div></div>`}
function accountContent(){if(accountSection==='orders')return `<section class="panel"><h2>รายการซื้อของฉัน</h2><div class="empty large-empty">${pixelIcon('chest')}<h3>ยังไม่มีรายการซื้อให้แสดง</h3><p>ร้านค้ายังไม่เปิดรับชำระ ระบบจริงจะแสดงเลขรายการ ยอดเงิน และสถานะส่งมอบที่นี่</p><a href="#shop" class="text-link">ดูของตกแต่ง</a></div></section>`;if(accountSection==='mail')return `<section class="panel"><h2>กล่องจดหมาย</h2><div class="empty large-empty">${pixelIcon('book')}<h3>เชื่อมตัวละครเพื่อดูของรอรับ</h3><p>เมื่อเปิดบริการ ของที่ส่งตอนออฟไลน์หรือกระเป๋าเต็มจะรอรับในกล่องจดหมาย</p><button class="text-button" data-account-tab="overview">ไปเชื่อมบัญชี</button></div></section>`;if(accountSection==='settings')return `<section class="panel"><h2>ตั้งค่าหน้าจอ</h2><p class="fine">บันทึกในเบราว์เซอร์นี้ โดยไม่ต้องเชื่อมบัญชีเกม</p><div class="setting-row"><label for="color-choice">รูปแบบสี</label><select id="color-choice"><option value="dark">เมืองยามค่ำ</option><option value="light">เมืองยามเช้า</option></select></div><div class="setting-row"><label for="reduce-motion">ลดการเคลื่อนไหว</label><input type="checkbox" id="reduce-motion"></div><p class="fine">ตั้งค่าบัญชีและการแจ้งเตือนจะพร้อมหลังเชื่อมระบบจริง</p></section>`;return `<div class="account-layout"><section class="account-panel"><h2>เชื่อมบัญชี Minecraft</h2><ol class="step-list"><li><span>01</span><div>เข้าเกมด้วยบัญชีของคุณ</div></li><li><span>02</span><div>ใช้ <code>/link</code> เพื่อรับรหัสครั้งเดียว</div></li><li><span>03</span><div>นำรหัสมากรอกด้านล่าง</div></li></ol><form id="link-form"><div class="field"><label for="link-code">รหัสจากเกม</label><input id="link-code" maxlength="12" autocomplete="off" aria-describedby="link-help" required></div><p id="link-help" class="fine">ยังไม่เชื่อมเซิร์ฟ จึงไม่สามารถตรวจรหัสได้</p><div class="actions"><button class="button" type="submit">ตรวจสอบรหัส</button></div><p id="link-error" class="error" role="status"></p></form></section><section class="panel"><h2>บัญชีเดียว ดูแลของครบ</h2><div class="benefit-row">${pixelIcon('chest')}<div><h3>รายการซื้อและใบเสร็จ</h3><p>ติดตามสถานะชำระเงินและการส่งมอบ</p></div></div><div class="benefit-row">${pixelIcon('book')}<div><h3>ของรอรับในเกม</h3><p>รับผ่านกล่องจดหมายเมื่อพร้อม</p></div></div><div class="benefit-row">${pixelIcon('banner')}<div><h3>ตัวละครและกิลด์</h3><p>ดูข้อมูลที่คุณอนุญาตให้แสดง</p></div></div><p class="fine">บริการเหล่านี้อยู่ในแผนเชื่อมระบบจริง</p></section></div>`}
function legalPage(kind){return `<div class="shell legal-page">${pageHead('LUMA SERVICE',kind==='privacy'?'ความเป็นส่วนตัว':'เงื่อนไขบริการ','ร่างสำหรับเตรียมเปิดบริการ ต้องระบุผู้ดำเนินการและช่องทางติดต่อก่อนใช้งานจริง')}<article class="article">${kind==='privacy'?'<h2>ข้อมูลในต้นแบบนี้</h2><p>หน้าเว็บยังไม่ขอรหัสผ่าน Minecraft ไม่ตรวจรหัส /link และไม่รับข้อมูลการชำระเงินจริง การเลือกธีมและลดการเคลื่อนไหวบันทึกในเบราว์เซอร์ของคุณ</p><h2>เมื่อเชื่อมบริการจริง</h2><p>แสดงวัตถุประสงค์ ระยะเวลาเก็บข้อมูล ผู้ให้บริการ และช่องทางขอเข้าถึงหรือลบข้อมูลก่อนเก็บ UUID ประวัติคำสั่งซื้อ หรือข้อมูลบัญชี</p>':'<h2>สถานะบริการ</h2><p>เว็บนี้เป็นต้นแบบ ระบบเกม สินค้า ราคา และกิจกรรมยังอยู่ระหว่างวางแผน ไม่มีการรับชำระหรือรับประกันวันเปิดเซิร์ฟ</p><h2>ก่อนเปิดร้านค้า</h2><p>ต้องประกาศรายละเอียดสินค้า รุ่นเกมที่รองรับ วิธีส่งของ การคืนเงิน และช่องทางติดต่อให้ครบก่อนเปิดรับชำระ</p>'}<a class="text-link" href="#home">กลับหน้าหลัก</a></article></div>`}
function globalSearch(){modal(`<h2 id="dialog-title">ค้นหาใน Luma</h2><div class="field"><label for="global-query">สถานที่ ระบบ หรือไอเทม</label><input id="global-query" type="search" placeholder="ธนาคาร ซ่อม เควส Halo" autocomplete="off"></div><div id="global-results" class="global-results">${searchResults('')}</div>`);document.querySelector('#global-query').focus()}
function searchResults(q){const term=q.trim().toLowerCase();const matches=[...zones.map(z=>({name:z.name,detail:z.services.join(' · '),type:'สถานที่',attr:`data-search-zone="${z.id}"`})),...guides.map(g=>({name:g.name,detail:g.summary,type:'คู่มือ',attr:`data-guide="${g.id}"`})),...products.map(p=>({name:p.name,detail:p.type,type:'สินค้า',attr:`data-search-product="${p.id}"`}))].filter(x=>`${x.name} ${x.detail}`.toLowerCase().includes(term));return matches.length?matches.slice(0,10).map(x=>`<button ${x.attr}><span>${x.name}<small>${x.detail}</small></span><span class="meta">${x.type}</span></button>`).join(''):'<div class="empty">ไม่พบรายการ ลองใช้ชื่อระบบหรือบริการอื่น</div>'}
function syncAccountControls(){const choice=document.querySelector('#color-choice');if(choice)choice.value=document.documentElement.dataset.theme;const motion=document.querySelector('#reduce-motion');if(motion)motion.checked=document.documentElement.dataset.motion==='reduce'}
document.addEventListener('click',e=>{const el=e.target.closest('button,a');if(!el)return;if(el.id==='menu-toggle'){const open=el.getAttribute('aria-expanded')!=='true';el.setAttribute('aria-expanded',String(open));document.querySelector('#primary-nav').classList.toggle('open',open)}if(el.id==='search-open')globalSearch();if(el.dataset.mapLink){activeZone=el.dataset.mapLink;dialog.close();if(location.hash==='#map')updateMap()}if(el.dataset.guideLink)setTimeout(()=>openGuide(el.dataset.guideLink),0);if(el.dataset.guide)openGuide(el.dataset.guide);if(el.dataset.searchZone){activeZone=el.dataset.searchZone;dialog.close();if(location.hash==='#map')updateMap();else location.hash='map'}if(el.dataset.searchProduct){const p=products.find(p=>p.id===el.dataset.searchProduct);dialog.close();location.hash='shop';setTimeout(()=>document.querySelector(`[data-product="${p.id}"]`)?.click(),0)}if(el.dataset.guideCategory){guideCategory=el.dataset.guideCategory;document.querySelector('#guide-results').innerHTML=guideCards();document.querySelectorAll('[data-guide-category]').forEach(b=>b.setAttribute('aria-pressed',String(b.dataset.guideCategory===guideCategory)))}if(el.dataset.accountTab){accountSection=el.dataset.accountTab;document.querySelector('#account-content').innerHTML=accountContent();document.querySelectorAll('[data-account-tab]').forEach(b=>b.setAttribute('aria-pressed',String(b.dataset.accountTab===accountSection)));syncAccountControls()}if(el.dataset.ranking){rankingCategory=el.dataset.ranking;document.querySelector('#ranking-title').textContent=rankingCategory;document.querySelectorAll('[data-ranking]').forEach(b=>b.setAttribute('aria-pressed',String(b.dataset.ranking===rankingCategory)))}if(el.closest('#primary-nav')){document.querySelector('#primary-nav').classList.remove('open');document.querySelector('#menu-toggle').setAttribute('aria-expanded','false')}});
document.addEventListener('input',e=>{if(e.target.id==='guide-search'){guideQuery=e.target.value.trim();document.querySelector('#guide-results').innerHTML=guideCards()}if(e.target.id==='global-query')document.querySelector('#global-results').innerHTML=searchResults(e.target.value)});
document.addEventListener('change',e=>{if(e.target.id==='color-choice'){document.documentElement.dataset.theme=e.target.value;try{localStorage.setItem('luma-theme',e.target.value)}catch{}themeLabel()}if(e.target.id==='reduce-motion'){document.documentElement.dataset.motion=e.target.checked?'reduce':'normal';try{localStorage.setItem('luma-motion',document.documentElement.dataset.motion)}catch{}}});
document.addEventListener('keydown',e=>{if((e.ctrlKey||e.metaKey)&&e.key.toLowerCase()==='k'){e.preventDefault();globalSearch()}});
try{document.documentElement.dataset.motion=localStorage.getItem('luma-motion')||'normal'}catch{}
